package com.zoro.zoromart.service;
import com.zoro.zoromart.dao.UserDAO;import com.zoro.zoromart.util.ValidationUtil;import com.zoro.zoromart.util.PasswordUtil;import java.sql.SQLException;import java.util.*;
/** Validates registration and authenticates users with BCrypt hashes. */
public class AuthService {private final UserDAO users;public AuthService(UserDAO users){this.users=users;}public Map<String,Object> register(String name,String email,String password,String role)throws SQLException{name=ValidationUtil.required(name,"name");email=ValidationUtil.email(email);password=ValidationUtil.required(password,"password");if(password.length()<8)throw new IllegalArgumentException("Password must be at least 8 characters");role=ValidationUtil.required(role,"role").toUpperCase(Locale.ROOT);if(!role.equals("BUYER")&&!role.equals("SELLER"))throw new IllegalArgumentException("Role must be BUYER or SELLER");if(users.byEmail(email)!=null)throw new IllegalArgumentException("Email already registered");long id=users.create(name,email,PasswordUtil.hash(password),role);return Map.of("id",id,"name",name,"email",email,"role",role);}public Map<String,Object> login(String email,String password)throws SQLException{email=ValidationUtil.email(email);Map<String,Object> u=users.byEmail(email);if(u==null||!PasswordUtil.matches(password,(String)u.get("passwordHash")))return null;u.remove("passwordHash");return u;}}
